// ======================== the browser
const server = http.createServer((req, res) => {
	const u = decodeURIComponent(req.url.split('?')[0]);
	if (u === '/api/mp') { req.resume(); req.on('end', () => { res.writeHead(200, { 'content-type': 'application/json' }); res.end('{}'); }); return; }
	const f = u.endsWith('/') ? u + 'index.html' : u;
	const base = /^\/(micasurvivor\/assets|overworld\/data|overworld\/item_icons)\//.test(f) ? AROOT : /^\/micasurvivor\//.test(f) ? MROOT : ROOT;
	fs.readFile(path.join(base, f), (e, d) => {
		if (e) { res.writeHead(404); res.end('nf'); return; }
		res.writeHead(200, { 'content-type': TYPES[path.extname(f)] || 'application/octet-stream' }); res.end(d);
	});
});
const SAVE = {
	v: 3, name: 'Trainer', created: 1, updated: 1, coins: 500,
	owned: { 4: { at: 1, from: 'starter' }, 25: { at: 1, from: 'gacha' } },
	shiny: {}, partner: 25, partnerShiny: false, starter: 4, personality: { trait: 'brave', scores: {} },
	upgrades: {}, ptm: {}, pz: {}, zmis: {}, tickets: { t1: 0, t10: 0 }, pity: {}, legends: {}, arenas: {}, itemsFound: {},
	evoMoves: {}, ach: {}, missions: {}, profile: { favs: [], title: '' }, modes: {}, pupgDone: true, pupg: {},
};
const BEFORE = (save) => {
	const H = window.__t = { frozen: false, pending: null };
	const realRaf = window.requestAnimationFrame.bind(window);
	window.requestAnimationFrame = cb => realRaf(ts => { if (!H.frozen) cb(ts); else H.pending = cb; });
	H.freeze = () => { H.frozen = true; };
	H.thaw = () => { if (!H.frozen) return; H.frozen = false; const cb = H.pending; H.pending = null; if (cb) realRaf(cb); };
	try {
		if (!sessionStorage.getItem('seeded')) {
			sessionStorage.setItem('seeded', '1');
			localStorage.setItem('micasurvivor_dev', 'dmega14');
			localStorage.setItem('micasurvivor_accounts', JSON.stringify({ guest: { name: 'Trainer', guest: true, created: 1 } }));
			localStorage.setItem('micasurvivor_session', JSON.stringify('guest'));
			localStorage.setItem('micasurvivor_save.guest', JSON.stringify(save));
		}
	} catch (e) { /* the test reports a boot failure */ }
	H.sturdy = () => { const pl = G.Game.player; H.hurts = 0; pl.hurt = function () { H.hurts++; }; pl.gainXp = () => 0; return pl; };
	H.unblock = () => {
		if (G.ExpEco && G.ExpEco.pick) { G.ExpEco.closePick(true); return; }
		if (G.Game.state === 'choice' || G.UI.isOpen('scr-item')) { const c = [...document.querySelectorAll('#item-cards .card')].pop(); if (c) c.click(); }
	};
	H.step = (n, dt = 1 / 30) => { for (let i = 0; i < n; i++) { H.unblock(); G.Game.debugStep(1, dt); } };
	H.thin = () => { for (const e of G.EnemyMgr.all()) if (!e.boss && !e.dead) { e.dead = true; e.fade = 0; } };
	H.quiet = () => { if (G.ExpClassic.run) G.ExpClassic.run.acc = -1e6; };
	/** the level-up screen as it opens: its cards */
	H.open = () => {
		G.Game.debugLevelUp();
		for (let i = 0; i < 3 && !G.UI.isOpen('scr-levelup'); i++) H.step(1);
		const offers = (G.RunUI.offers || []).map(c => ({ key: c.key, type: c.type, title: c.title, img: c.img || null, sprite: c.sprite || null }));
		const els = [...document.querySelectorAll('#cards .card')].map(el => ({ title: el.querySelector('.nm').innerText, img: (el.querySelector('img.ico-item') || {}).src || null, mon: !!el.querySelector('.ico-mon canvas') }));
		const note = (() => { const n = document.getElementById('lvl-note'); return n && !n.classList.contains('hidden') ? n.innerText : ''; })();
		return { offers, els, note, level: G.Game.player.level };
	};
	/** click card i of the open level-up screen */
	H.pick = i => { const els = [...document.querySelectorAll('#cards .card')]; if (els[i]) els[i].click(); H.step(1); };
	/** level up (never picking a Mega: the first card that isn't a new move / Mega / "Not yet", or a branch) until level n */
	H.levelTo = n => {
		const pl = G.Game.player; let g = 0;
		while (pl.level < n && g++ < 200) {
			H.thin();
			const s = H.open();
			let i = s.offers.findIndex(c => c.type !== 'new' && !/^xmega/.test(c.key || ''));
			if (s.offers.some(c => /^xmega/.test(c.key || ''))) i = s.offers.findIndex(c => c.key === 'xmega:later');
			H.pick(Math.max(0, i));
		}
		return pl.level;
	};
	H.lose = t => { G.Game.debugTime(t); G.Game.endRun(false); return window.__sum; };
};

